 if(path==="/api/transactions"&&m==="POST"){if(!write(p))return J({ok:false,error:"غير مصرح"},403);const b=await parse(r);if(!b?.subject||!b?.entity||!b?.type)return J({ok:false,error:"الحقول الأساسية مطلوبة"},422);if(b.identity_number&&(!/^[12]\d{9}$/.test(b.identity_number)||b.type!=="وارد"))return J({ok:false,error:"رقم الهوية غير صحيح"},422);const dept=b.type==="وارد"?"السكرتارية":b.department,t=now(),sla=+b.sla_days||3,tmp=crypto.randomUUID();const x=await db.prepare("INSERT INTO transactions (reference,type,priority,subject,entity,identity_number,department,status,sla_days,due_at,created_at,updated_at,created_by,external_reference,external_date,channel,confidentiality,keywords,linked_transaction_id,assignee_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(tmp,b.type,b.priority||"عادية",b.subject,b.entity,b.identity_number||null,dept,"قيد الإجراء",sla,await due(db,t,sla),t,t,p.id,b.external_reference||null,b.external_date||null,b.channel||null,b.confidentiality||"عادي",b.keywords||null,b.linked_transaction_id||null,b.assignee_id||null).run();const id=x.meta.last_row_id,ref=`${b.type[0]}-${new Date().getUTCFullYear()}-${String(id).padStart(4,"0")}`;await db.batch([db.prepare("UPDATE transactions SET reference=? WHERE id=?").bind(ref,id),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"استلام","تسجيل المعاملة",dept,p.name,t)]);await log(db,r,"create","transaction",id,{ref});return J({ok:true,data:await detail(db,id)},201)}
 const tm=path.match(/^\/api\/transactions\/(\d+)(?:\/(transfer|comments|attachments|close|reopen|cancel|remind))?$/);if(tm){const id=+tm[1],action=tm[2],[t,code]=await access(db,p,id);if(!t)return J({ok:false,error:code===404?"غير موجود":"غير مصرح"},code);if(m==="GET"&&!action){await log(db,r,"view","transaction",id);return J({ok:true,data:await detail(db,id)})}if(action==="transfer"&&m==="POST"){if(!route(p))return J({ok:false,error:"غير مصرح بالتحويل"},403);const b=await parse(r);if(!b?.department||!b?.note?.trim())return J({ok:false,error:"الإدارة وتعليق التحويل مطلوبان"},422);const d=await db.prepare("SELECT sla_days FROM departments WHERE name=? AND active=1").bind(b.department).first(),ts=now();await db.batch([db.prepare("UPDATE transactions SET department=?,status='قيد الإجراء',due_at=?,updated_at=? WHERE id=?").bind(b.department,await due(db,ts,d?.sla_days||3),ts,id),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"تحويل",b.note,b.department,p.name,ts),db.prepare("INSERT INTO notifications (user_id,transaction_id,title,body,created_at) SELECT id,?,?,?,? FROM app_users WHERE department=? AND active=1").bind(id,"معاملة محولة",t.reference,ts,b.department)]);await log(db,r,"transfer","transaction",id,b);return J({ok:true,data:await detail(db,id)})}if(action==="remind"&&m==="POST"){if(!route(p))return J({ok:false,error:"غير مصرح بإرسال التنبيه"},403);if(t.type!=="وارد"||["مكتملة","مغلقة","ملغاة"].includes(t.status)||new Date(t.due_at)>=new Date())return J({ok:false,error:"التنبيه مخصص للخطابات الواردة المتأخرة"},422);const b=await parse(r),body=b?.body?.trim()||`يرجى معالجة الخطاب الوارد المتأخر والرد عليه`,ts=now();let recipients;if(t.assignee_id){recipients=await db.prepare("SELECT id FROM app_users WHERE id=? AND active=1").bind(t.assignee_id).all()}else{recipients=await db.prepare("SELECT id FROM app_users WHERE department=? AND active=1").bind(t.department).all()}if(!recipients.results.length)return J({ok:false,error:"لا يوجد مستخدم مسؤول مسجل في الوحدة الحالية"},422);await db.batch([...recipients.results.map(x=>db.prepare("INSERT INTO notifications (user_id,transaction_id,title,body,created_at) VALUES (?,?,?,?,?)").bind(x.id,id,"تنبيه تأخر خطاب وارد",body,ts)),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"إشعار تأخير",body,t.department,p.name,ts)]);await log(db,r,"remind","transaction",id,{recipients:recipients.results.length,body});return J({ok:true,recipients:recipients.results.length})}if(action==="comments"&&m==="POST"){const b=await parse(r);if(!b?.body?.trim())return J({ok:false,error:"الملاحظة مطلوبة"},422);await db.batch([db.prepare("INSERT INTO comments (transaction_id,body,author,created_at) VALUES (?,?,?,?)").bind(id,b.body,p.name,now()),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"ملاحظة",b.body,t.department,p.name,now())]);await log(db,r,"comment","transaction",id);return J({ok:true})}if(action==="attachments"&&m==="POST"){const f=(await r.formData()).get("file"),ok=["application/pdf","image/png","image/jpeg"];if(!(f instanceof File)||f.size>10485760||!ok.includes(f.type))return J({ok:false,error:"PDF أو صورة بحد أقصى 10MB"},422);const key=`transactions/${id}/${crypto.randomUUID()}-${f.name.replace(/[^\p{L}\p{N}._-]/gu,"_")}`;await env.BUCKET.put(key,f.stream(),{httpMetadata:{contentType:f.type}});await db.batch([db.prepare("INSERT INTO attachments (transaction_id,object_key,filename,content_type,size_bytes,uploaded_by,created_at) VALUES (?,?,?,?,?,?,?)").bind(id,key,f.name,f.type,f.size,p.name,now()),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"مرفق",f.name,t.department,p.name,now())]);await log(db,r,"upload","attachment",id);return J({ok:true})}if(["close","reopen","cancel"].includes(action)&&m==="POST"){if(!route(p))return J({ok:false,error:"غير مصرح"},403);if(action==="close"&&t.department==="الشؤون المالية"&&!Number((await db.prepare("SELECT COUNT(*) n FROM attachments WHERE transaction_id=?").bind(id).first()).n))return J({ok:false,error:"المرفق المالي إلزامي"},422);const st=action==="close"?"مغلقة":action==="cancel"?"ملغاة":"قيد الإجراء",ts=now();await db.batch([db.prepare("UPDATE transactions SET status=?,cancelled_at=?,updated_at=? WHERE id=?").bind(st,action==="cancel"?ts:null,ts,id),db.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,action,st,t.department,p.name,ts)]);await log(db,r,action,"transaction",id);return J({ok:true})}}
 const am=path.match(/^\/api\/attachments\/(\d+)\/download$/);if(am){const a=await db.prepare("SELECT a.*,t.department FROM attachments a JOIN transactions t ON t.id=a.transaction_id WHERE a.id=?").bind(+am[1]).first();if(!a||(!all(p)&&a.department!==p.department))return J({ok:false,error:"غير مصرح"},403);const o=await env.BUCKET.get(a.object_key);await log(db,r,"download","attachment",a.id);return new Response(o.body,{headers:{"content-type":a.content_type,"content-disposition":`attachment; filename*=UTF-8''${encodeURIComponent(a.filename)}`}})}
 if(path==="/api/notifications"&&m==="GET"){const x=await db.prepare("SELECT n.*,t.reference,t.subject,t.entity,t.status,t.type,t.due_at,t.assignee_id,COALESCE(a.name,t.department) responsible_name,CAST(MAX(0,julianday('now')-julianday(t.due_at)) AS INTEGER) delay_days FROM notifications n LEFT JOIN transactions t ON t.id=n.transaction_id LEFT JOIN app_users a ON a.id=t.assignee_id WHERE n.user_id=? ORDER BY n.created_at DESC LIMIT 200").bind(p.id).all();return J({ok:true,data:x.results})}
 for(const [name,table] of [["entities","entities"],["departments","departments"],["holidays","holidays"]])if(path===`/api/${name}`&&m==="GET"){const q=db.prepare(`SELECT * FROM ${table} ORDER BY id DESC LIMIT 200`);return J({ok:true,data:(await q.all()).results})}
