 if(path.startsWith("/api/reports/")){const rows=await list(db,u,p),esc=v=>`"${String(v??"").replaceAll('"','""')}"`;let filtered=rows;if(path.includes("late"))filtered=rows.filter(x=>x.status==="متأخرة");const csv=["الرقم,النوع,الأولوية,الموضوع,الجهة,الإدارة,الحالة,سبب التأخير",...filtered.map(x=>[x.reference,x.type,x.priority,x.subject,x.entity,x.department,x.status,x.delay_reason].map(esc).join(","))].join("\n");await log(db,r,"export","report",path);return new Response("\ufeff"+csv,{headers:{"content-type":"text/csv; charset=utf-8","content-disposition":"attachment; filename=report.csv"}})}
 if(path==="/api/metrics"){const scopedWhere=all(p)?"":" WHERE department=?",bind=all(p)?[]:[p.department||"__none__"];const [summary,byDepartment,monthly,sla]=await Promise.all([db.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN type='وارد' THEN 1 ELSE 0 END) incoming,SUM(CASE WHEN type='صادر' THEN 1 ELSE 0 END) outgoing,SUM(CASE WHEN status='متأخرة' OR (status NOT IN ('مكتملة','مغلقة','ملغاة') AND datetime(due_at)<datetime('now')) THEN 1 ELSE 0 END) late,SUM(CASE WHEN status IN ('مكتملة','مغلقة') THEN 1 ELSE 0 END) completed FROM transactions${scopedWhere}`).bind(...bind).first(),db.prepare(`SELECT department,COUNT(*) total,SUM(CASE WHEN status IN ('مكتملة','مغلقة') THEN 1 ELSE 0 END) completed,SUM(CASE WHEN status='متأخرة' OR (status NOT IN ('مكتملة','مغلقة','ملغاة') AND datetime(due_at)<datetime('now')) THEN 1 ELSE 0 END) late FROM transactions${scopedWhere} GROUP BY department ORDER BY total DESC`).bind(...bind).all(),db.prepare(`SELECT strftime('%Y-%m',created_at) month,SUM(CASE WHEN type='وارد' THEN 1 ELSE 0 END) incoming,SUM(CASE WHEN type='صادر' THEN 1 ELSE 0 END) outgoing FROM transactions${scopedWhere} GROUP BY month ORDER BY month DESC LIMIT 6`).bind(...bind).all(),db.prepare(`SELECT ROUND(AVG(CASE WHEN status IN ('مكتملة','مغلقة') THEN julianday(updated_at)-julianday(created_at) END),1) avg_completion_days,ROUND(100.0*SUM(CASE WHEN datetime(updated_at)<=datetime(due_at) THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),1) compliance FROM transactions${scopedWhere}`).bind(...bind).first()]);return J({ok:true,summary,departments:byDepartment.results,monthly:monthly.results.reverse(),sla})}
 return J({ok:false,error:"المسار غير موجود"},404)
