export default{async fetch(r,env){const u=new URL(r.url),s=Date.now();try{const x=u.pathname.startsWith("/api/")?await api(r,env,u):await env.ASSETS.fetch(r);console.log(JSON.stringify({method:r.method,path:u.pathname,status:x.status,ms:Date.now()-s}));return x}catch(e){console.error(e);return J({ok:false,error:"خطأ داخلي",request_id:crypto.randomUUID()},500)}}};
